use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm;
use crate::aap::caps::types::{AgentResponse, LlmError};

struct Node;

/// The node's authority is its `with` clause and nothing more:
/// `aap:caps/kb-read@0.1.0` (read-only, 'knowledge-base') and
/// `aap:caps/tool-llm@0.1.0` ([lookup]). No other interface is imported, so no
/// other interface can be called — that is the point of the grant.
const MAX_ROUNDS: usize = 8;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // requires len(question) <= 512. The contract says every input satisfies
        // this; we fail closed rather than trust it blindly, since `question` is
        // bounded-but-adversarial free text.
        if ctx.question.len() > 512 {
            return ResponseResult::Error(LlmError {
                message: "precondition violated: question exceeds 512 bytes".into(),
            });
        }

        let system = format!(
            "You are a customer-support agent. Intent: {}. Answer the question \
             using only the provided knowledge; call the `lookup` tool if you \
             need more from the knowledge base.",
            intent_label(ctx.intent),
        );

        // Seed the prompt with the question and any knowledge already attached.
        let mut prompt = String::new();
        if !ctx.knowledge.is_empty() {
            prompt.push_str("Knowledge:\n");
            for k in &ctx.knowledge {
                prompt.push_str("- ");
                prompt.push_str(k);
                prompt.push('\n');
            }
            prompt.push('\n');
        }
        prompt.push_str("Question: ");
        prompt.push_str(&ctx.question);

        // Tool-orchestration loop. The model either answers (text) or asks for a
        // tool (call). The only tool this node can actually perform is `lookup`,
        // because `kb-read` is the only tool interface in its world.
        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(&system, &prompt) {
                tool_llm::Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                tool_llm::Reply::Call(req) => {
                    if req.tool == "lookup" {
                        let rows = kb_read::lookup(&req.query);
                        prompt.push_str("\n\nLookup results for ");
                        prompt.push_str(&req.query);
                        prompt.push_str(":\n");
                        if rows.is_empty() {
                            prompt.push_str("(no results)\n");
                        } else {
                            for row in rows {
                                prompt.push_str("- ");
                                prompt.push_str(&row);
                                prompt.push('\n');
                            }
                        }
                    } else {
                        // Any other tool is outside this node's authority. We do
                        // not invoke it and do not fabricate a result; we tell the
                        // model so it can answer with what it has.
                        prompt.push_str("\n\nTool `");
                        prompt.push_str(&req.tool);
                        prompt.push_str("` is not available to this node. Answer \
                                         using the knowledge already provided.\n");
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool-orchestration loop did not converge on an answer".into(),
        })
    }
}

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

export!(Node);
